{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시가 청년교육 프로그램 관련 교육교재 개발과 청년교육 강사 양성까지 지원할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시장은 청년교육체계 마련과 효과적 시행을 위하여 교육교재 개발, 청년교육 강사 양성 등을 지원할 수 있다. 따라서 청년교육 프로그램을 만드는 단체라도 시장이 청년교육체계 마련·효과적 시행을 위해 교육교재 개발이나 청년교육 강사 양성을 지원하는 것은 가능하다. 다만 지원 여부는 시장의 재량이며, 경비의 지원 방법·절차 등 필요한 사항은 「서울특별시 지방보조금 관리 조례」에 따른다.",
          "b_ids": "청년:제11조제5항, 청년:제23조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
